PLAN_TECHNIQUE:
{
  "description": "When the plan builds something that's a reusable idea for a kind of sound (devices loaded and set up to a purpose), give it technique: its name, what it fits (narrowly), and the idea (the chain and why each part), with the settings that matter and substitutes when you know them. After your answer Kumi asks the producer whether to keep it; don't ask or mention it. Leave it out for one-off or routine changes and fixes.",
  "schema": {
    "type": "object",
    "additionalProperties": false,
    "required": [
      "name",
      "fits",
      "idea"
    ],
    "properties": {
      "name": {
        "type": "string",
        "maxLength": 48
      },
      "fits": {
        "type": "string",
        "maxLength": 160,
        "description": "The kind of sound or request it fits, narrowly"
      },
      "idea": {
        "type": "string",
        "maxLength": 1200,
        "description": "The chain and why each part"
      },
      "settings": {
        "type": "string",
        "maxLength": 600,
        "description": "The settings that mattered"
      },
      "substitutes": {
        "type": "string",
        "maxLength": 400,
        "description": "What to use when a part isn't available"
      },
      "recipe": {
        "type": "string",
        "maxLength": 64,
        "description": "A recipe for the fixed parts, by name"
      },
      "source": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "title": {
            "type": "string",
            "maxLength": 160
          },
          "url": {
            "type": "string",
            "maxLength": 300
          }
        }
      },
      "replaces": {
        "type": "string",
        "pattern": "^t\\d{1,4}$",
        "description": "The id of a technique this refines"
      }
    },
    "description": "When this plan builds a reusable idea for a kind of sound: what makes it work (the chain and why, the settings that matter, substitutes, where it came from). Kumi asks the producer after your answer whether to keep it."
  }
}
